@startuml

enum SubscriptionType {
  Monthly
  Annual
}

enum ServiceType {
  WeightRoom
  SwimmingPool
  ClimbingWall
  Sauna
  TurkishBath
}

class Customer {
  + name : string
  + surname : string
  + age : int
  + address : string
  + profession : string
}

class Subscription {
  + type : SubscriptionType
}

class Service {
  + type : ServiceType
}

class WorkoutPlan {
  + frequency : int
}

class Exercise {
  + name : string
  + repetitions : int
}

class MedicalCheck {
  + date : date
  + weight : float
  + bodyFat : float
  + electrocardiogram : string
  + restingHeartbeat : int
  + stressHeartbeat : int
}

class MedicalStaff {
  + name : string
}

class Diet {
  + description : string
}

class FinancialRecord {
  + amount : float
  + date : date
}

Customer "1" -- "1" Subscription : has
Customer "1" -- "*" Service : requests
Customer "1" -- "0..1" WorkoutPlan : is associated with
Customer "1" -- "0..*" MedicalCheck : undergoes
Customer "1" -- "0..1" Diet : follows
MedicalStaff "1" -- "*" MedicalCheck : performs
MedicalStaff "1" -- "*" Diet : defines

WorkoutPlan "1" *-- "*" Exercise : defines
WorkoutPlan "0..1" -- "0..*" Service : includes

@enduml

